import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"32、【恒】 巽下震上","description":"周易尚氏学 - 32、【恒】 巽下震上","frontmatter":{"title":"32、【恒】 巽下震上","description":"周易尚氏学 - 32、【恒】 巽下震上"},"headers":[],"relativePath":"zh/classics/shangshi/037.md","filePath":"zh/classics/shangshi/037.md"}'),h={name:"zh/classics/shangshi/037.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_32、【恒】-巽下震上" tabindex="-1">32、【恒】 巽下震上 <a class="header-anchor" href="#_32、【恒】-巽下震上" aria-label="Permalink to “32、【恒】 巽下震上”">​</a></h1><p>咸男下女。男求女。得婚姻之正。夫妇之道既立。则长男在前。长女在后。夫倡妇随。终身以之。故受之以恒。恒常也。久也。卦六爻皆有应。故亨利贞。易林大畜之未济云。乾坤利贞。乳生六子。利贞者和合也。二五应初承重阳。四临重阴。故曰利有攸往。虞翻谓终变成益者是也。</p><p>彖曰。恒。久也。刚上而柔下。雷风相与。巽而动。刚柔皆应。恒。恒亨无咎利贞。久于其道也。天地之道。恒久而不巳也。利有攸往。终则有始也。日月得天而能久照。四时变化而能大成。圣人久于其道而天下化成。观其所恒。而天地万物之情可见矣。</p><p>泰初四相上下成震巽。故曰刚上而柔下。震巽相反复。乾坤者震巽之终。震巽者乾坤之始。故曰终则有始。蛊先甲三日。后甲三日。终则有始。与此理同也。夫妇者天地也。天地之道。循环往来。恒久不已。乾为日。兑为月。日月久照。恒也。震为春。巽为夏。兑秋。乾冬。四时反复。无有穷期。恒也。乾为圣人。震巽为草木。故曰万物之情。</p><p>象曰。雷风。恒。君子以立不易方。</p><p>雷风同声相应。可常可久。立而易方。则不恒矣。故此卦六爻皆有应。而爻辞皆不取。论语有勇知方。注。方义也。立不易方。即蹈义而行。无或违也。</p><p>初六。浚恒。贞凶。无攸利。</p><p>浚深也。虞翻云。乾初为渊故深。深谓阳。乃泰初阳上居四。四阴下居初。虽皆失位。而仍有相求相交之象。故曰浚恒。乃四阳为二三所隔。不能应初。若初则可应四也。惟初远应四。则有近不承阳之嫌。为二三所忌。故曰贞凶。无攸利。贞卜问。巽为利也。</p><h3 id="象曰。浚恒之凶。始求深也。" tabindex="-1">象曰。浚恒之凶。始求深也。 <a class="header-anchor" href="#象曰。浚恒之凶。始求深也。" aria-label="Permalink to “象曰。浚恒之凶。始求深也。”">​</a></h3><p>又在初称始。宜静不宜动。况阴居初失位。尤不宜动。以违恒久之义。乃初六求与四阳交。不知二三之有厉。故曰浚恒之凶。始求深也。言凶之故在初六求与四交也。焦氏易林泰之恒云。蔡倏适楚。流连江滨。逾日历月。思其后君。粪为草莽。故为蔡。丛木为楚。故震为楚。言初求四。故曰蔡侯适楚。乾为江海。初在乾下。故曰流连江滨。乾为日兑为月。初前临乾兑。故曰逾日历月。初求交四。震为君。故曰思其后君。林词专释此爻与四之关系。而曰思其后君。释求深之义。尤为明白。故本焦义以为诂。</p><p>九二。悔亡。</p><p>二不当位。前临重阳。宜有悔矣。然得中位。进虽不利。中正自守，亦无悔也。</p><h3 id="象曰。九二悔亡。能久中也。" tabindex="-1">象曰。九二悔亡。能久中也。 <a class="header-anchor" href="#象曰。九二悔亡。能久中也。" aria-label="Permalink to “象曰。九二悔亡。能久中也。”">​</a></h3><p>乾为久。为三四所隔。不能应五。故久于中。卦以恒为义。久中故悔亡。</p><p>九三。不恒其德。或承之羞。贞吝。</p><p>乾为德。三承乘皆阳。宜静不宜动。倘亟于应上。而四或害之。则羞吝生矣。故贞吝也。又三居巽上。下桡。进退不定。亦不恒之一因也。</p><h3 id="象曰。不恒其德。无所容也。" tabindex="-1">象曰。不恒其德。无所容也。 <a class="header-anchor" href="#象曰。不恒其德。无所容也。" aria-label="Permalink to “象曰。不恒其德。无所容也。”">​</a></h3><p>乾为德。承乘皆阳。进退有阻。故曰无所容。</p><p>九四。田无禽。</p><p>震为田猎。禽获也。下应初。三二遇敌。受阻。故无禽。按四前临重阴。例之豫四。大壮解丰。四爻皆吉。兹独不吉者。卦以恒久贞定为义。故不取利往也。</p><h3 id="象曰。大非其位。安得禽也。" tabindex="-1">象曰。大非其位。安得禽也。 <a class="header-anchor" href="#象曰。大非其位。安得禽也。" aria-label="Permalink to “象曰。大非其位。安得禽也。”">​</a></h3><p>乾为久。乾四失位。故曰久非其位。</p><p>六五。恒其德。贞妇人吉。夫子凶。</p><p>二五为夫妇。乾为德。六五下遇重阳。而正应在九二。通利极矣。阴得阳应。终身顺承。故贞妇人吉。乾为夫。大过九二。老夫得女妻是也。故夫子谓九二。六五者九二之妇。本为正应。然二着应五而从妇。则三四遇敌。横犯灾难。故曰夫子凶。大畜初九曰。不犯灾。需初九曰。不犯难行。二卦初九。皆有正应。而皆二三得敌。故日灾难。兹与之同。</p><h3 id="象曰。妇人贞吉。从一而终也。夫子制义。从妇凶也。" tabindex="-1">象曰。妇人贞吉。从一而终也。夫子制义。从妇凶也。 <a class="header-anchor" href="#象曰。妇人贞吉。从一而终也。夫子制义。从妇凶也。" aria-label="Permalink to “象曰。妇人贞吉。从一而终也。夫子制义。从妇凶也。”">​</a></h3><p>五应二。故曰从一而终。坤为义。乾制义者也。阳得阴应。本无足贵。况应之而犯灾难乎。故曰从妇凶也。</p><p>上六。振恒。凶。</p><p>上六居动之极。故日振恒。振起也。卦以贞静恒久为义。振则于恒德或违。故凶。</p><h3 id="象曰。振恒在上。大无功也。" tabindex="-1">象曰。振恒在上。大无功也。 <a class="header-anchor" href="#象曰。振恒在上。大无功也。" aria-label="Permalink to “象曰。振恒在上。大无功也。”">​</a></h3><p>交至上而穷。不宜动。大谓三。三欲应上。为四所隔。故曰大无功。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
